// Türkçe yazının seçili dildeki karşılığı (yoksa kendisi)
export function tr(s) {
    if (IDX < 0 || typeof s !== 'string') return s;
    const e = D[s];
    return (e && e[IDX]) || s;
}
// Değişkenli yazı: tf('{0}. BÖLÜME GEÇ', 3)
export function tf(key, ...a) { return tr(key).replace(/\{(\d)\}/g, (m, i) => a[+i] !== undefined ? a[+i] : ''); }
// Sayı biçimi (1.234 / 1,234)
export const numFmt = n => n.toLocaleString(lang === 'tr' ? 'tr-TR' : lang === 'ru' ? 'ru-RU' : lang === 'de' ? 'de-DE' : lang === 'nl' ? 'nl-NL' : lang === 'fr' ? 'fr-FR' : 'en-US');
// Balyoz ve kalkan yazısı (kullanıcının isteği: Türkçede YARGI / DİN, bütün diğer dillerde JUDGE / Relig)
export const HAMMER_WORD = lang === 'tr' ? 'YARGI' : 'JUDGE';
export const SHIELD_WORD = lang === 'tr' ? 'DİN' : 'Relig';
// Sayfadaki sabit yazılar: data-t="Türkçe yazı" olan öğeler
export function translateDom(root = document) {
    root.querySelectorAll('[data-t]').forEach(el => { el.textContent = tr(el.dataset.t); });
    document.documentElement.lang = lang;
}
